import{_ as t,o,c as a,ae as n}from"./chunks/framework.BCZ_EjGL.js";const p=JSON.parse('{"title":"AskBot AI v1.0.0","description":"","frontmatter":{},"headers":[],"relativePath":"v1.0.0/index.md","filePath":"v1.0.0/index.md"}'),i={name:"v1.0.0/index.md"};function s(r,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="askbot-ai-v1-0-0" tabindex="-1">AskBot AI v1.0.0 <a class="header-anchor" href="#askbot-ai-v1-0-0" aria-label="Permalink to &quot;AskBot AI v1.0.0&quot;">​</a></h1><p>Welcome to the official documentation for <strong>v1.0.0</strong> of the <strong>AskBot AI</strong> Custom Widget for SAP Analytics Cloud.</p><p>AskBot AI is an interactive, AI-powered chatbot designed to enhance user engagement within your SAC stories and applications. It provides a seamless communication layer, allowing users to interact with a knowledge base, submit forms, and receive intelligent responses.</p><hr><h2 id="🚀-key-features" tabindex="-1">🚀 Key Features <a class="header-anchor" href="#🚀-key-features" aria-label="Permalink to &quot;🚀 Key Features&quot;">​</a></h2><ul><li><strong>Interactive Chat Interface</strong>: A modern, bubble-style chat UI that supports markdown for rich message formatting.</li><li><strong>AI-Powered Knowledge Base</strong>: Easily manage and search Q&amp;A pairs (QA pairs) to provide instant answers to common user questions.</li><li><strong>Dynamic Form Collection</strong>: Build and display custom forms within the chat to collect structured data from your users.</li><li><strong>Deep SAC Integration</strong>: Fully integrated with the SAP Analytics Cloud event bus and scripting capabilities.</li><li><strong>Voice &amp; Accessibility</strong>: Support for microphone controls and voice interaction.</li></ul><hr><h2 id="📦-download-installation" tabindex="-1">📦 Download &amp; Installation <a class="header-anchor" href="#📦-download-installation" aria-label="Permalink to &quot;📦 Download &amp; Installation&quot;">​</a></h2><p>To use this version in your SAP Analytics Cloud environment, you need to download the widget configuration file (JSON) and upload it to your SAC tenant.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This version is stable and recommended for production use.</p></div><p><a href="./../download"><strong>Download AskBotAI.json</strong></a></p><hr><h2 id="📖-core-documentation" tabindex="-1">📖 Core Documentation <a class="header-anchor" href="#📖-core-documentation" aria-label="Permalink to &quot;📖 Core Documentation&quot;">​</a></h2><p>Explore the following sections to get the most out of AskBot AI:</p><ul><li><strong><a href="./guide/lifecycle">Lifecycle Overview</a></strong>: Understand the initialization, connection, and disposal phases of the widget.</li><li><strong><a href="./api/addQA">API Reference</a></strong>: Detailed documentation of all available JavaScript methods, including <code>addQA</code>, <code>sendMessage</code>, and <code>addForm</code>.</li><li><strong><a href="./api/event-onInitialization">Events Reference</a></strong>: Learn about the events triggered by the widget, such as <code>onMessageSent</code> and <code>onFormSubmitted</code>.</li><li><strong><a href="./api/types">Types &amp; Data Structures</a></strong>: Specification of the data objects used throughout the API.</li></ul><hr><h2 id="🛠️-need-help" tabindex="-1">🛠️ Need Help? <a class="header-anchor" href="#🛠️-need-help" aria-label="Permalink to &quot;🛠️ Need Help?&quot;">​</a></h2><p>If you have questions or need assistance with implementation, please refer to the <a href="/about">About Page</a></p>',18)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
